import csv
import json
import math
from datetime import datetime

# ── Load Data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append({
            "date": row["Date"],
            "price": float(row["Crude_Oil_Price"])
        })

# ── Parse dates ────────────────────────────────────────────────────────────
for r in rows:
    parts = r["date"].split("-")
    r["year"] = int(parts[0])
    r["month"] = int(parts[1])
    r["decade"] = (r["year"] // 10) * 10

prices = [r["price"] for r in rows]
dates_str = [r["date"] for r in rows]
n = len(prices)

# ── KPI Calculations ──────────────────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
price_range = max_price - min_price
mean_price = sum(prices) / n
sorted_prices = sorted(prices)
median_price = (sorted_prices[n // 2 - 1] + sorted_prices[n // 2]) / 2 if n % 2 == 0 else sorted_prices[n // 2]
std_dev = math.sqrt(sum((p - mean_price) ** 2 for p in prices) / n)

# Percentiles
def percentile(data, pct):
    idx = (pct / 100) * (len(data) - 1)
    lower = int(math.floor(idx))
    upper = int(math.ceil(idx))
    if lower == upper:
        return data[lower]
    return data[lower] + (data[upper] - data[lower]) * (idx - lower)

p10 = percentile(sorted_prices, 10)
p25 = percentile(sorted_prices, 25)
p75 = percentile(sorted_prices, 75)
p90 = percentile(sorted_prices, 90)

# CAGR
first_price = prices[0]
last_price = prices[-1]
first_year = rows[0]["year"]
last_year = rows[-1]["year"]
years_span = last_year - first_year
cagr = (last_price / first_price) ** (1 / years_span) - 1

# Month-over-month changes
mom_abs_changes = []
mom_pct_changes = []
for i in range(1, n):
    abs_change = prices[i] - prices[i - 1]
    pct_change = (abs_change / prices[i - 1]) * 100 if prices[i - 1] != 0 else 0
    mom_abs_changes.append({
        "from_date": dates_str[i - 1],
        "to_date": dates_str[i],
        "abs_change": abs_change,
        "pct_change": pct_change
    })
    mom_pct_changes.append(pct_change)

max_mom_abs = max(mom_abs_changes, key=lambda x: abs(x["abs_change"]))
max_mom_pct = max(mom_abs_changes, key=lambda x: abs(x["pct_change"]))

# Year-over-year changes (same month, previous year)
yoy_changes = []
for i in range(12, n):
    yoy_change = (prices[i] - prices[i - 12]) / prices[i - 12] * 100 if prices[i - 12] != 0 else 0
    yoy_changes.append({
        "date": dates_str[i],
        "yoy_pct": yoy_change
    })

max_yoy = max(yoy_changes, key=lambda x: abs(x["yoy_pct"]))

# ── Decade Analysis ───────────────────────────────────────────────────────
decades = {}
for r in rows:
    d = r["decade"]
    if d not in decades:
        decades[d] = []
    decades[d].append(r["price"])

decade_stats = []
for decade in sorted(decades.keys()):
    dp = decades[decade]
    d_mean = sum(dp) / len(dp)
    d_std = math.sqrt(sum((p - d_mean) ** 2 for p in dp) / len(dp))
    d_min = min(dp)
    d_max = max(dp)
    d_range = d_max - d_min
    d_cv = (d_std / d_mean * 100) if d_mean != 0 else 0
    decade_stats.append({
        "decade": f"{decade}s",
        "count": len(dp),
        "mean": round(d_mean, 2),
        "std": round(d_std, 2),
        "cv": round(d_cv, 1),
        "min": round(d_min, 2),
        "max": round(d_max, 2),
        "range": round(d_range, 2)
    })

highest_avg_decade = max(decade_stats, key=lambda x: x["mean"])

# ── Top shocks (largest absolute MoM moves) ──────────────────────────────
top_shocks = sorted(mom_abs_changes, key=lambda x: abs(x["abs_change"]), reverse=True)[:10]

# ── Annual averages ───────────────────────────────────────────────────────
yearly = {}
for r in rows:
    y = r["year"]
    if y not in yearly:
        yearly[y] = []
    yearly[y].append(r["price"])

annual_avg = []
for y in sorted(yearly.keys()):
    yp = yearly[y]
    annual_avg.append({
        "year": y,
        "avg": round(sum(yp) / len(yp), 2),
        "min": round(min(yp), 2),
        "max": round(max(yp), 2)
    })

# ── Build chart data for JS ──────────────────────────────────────────────
chart_dates_json = json.dumps(dates_str)
chart_prices_json = json.dumps(prices)

# Decade chart data
decade_labels = json.dumps([d["decade"] for d in decade_stats])
decade_means = json.dumps([d["mean"] for d in decade_stats])
decade_stds = json.dumps([d["std"] for d in decade_stats])
decade_ranges = json.dumps([d["range"] for d in decade_stats])

# Annual chart data
annual_labels = json.dumps([str(a["year"]) for a in annual_avg])
annual_avgs = json.dumps([a["avg"] for a in annual_avg])
annual_mins = json.dumps([a["min"] for a in annual_avg])
annual_maxs = json.dumps([a["max"] for a in annual_avg])

# MoM volatility chart data
mom_dates = [mom_abs_changes[i]["to_date"] for i in range(len(mom_abs_changes))]
mom_pcts = [mom_abs_changes[i]["pct_change"] for i in range(len(mom_abs_changes))]
mom_dates_json = json.dumps(mom_dates)
mom_pcts_json = json.dumps(mom_pcts)

# ── Build HTML ────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Crude Oil Price Trends: A Historical Analysis (1970–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.1.0/dist/chartjs-plugin-annotation.min.js"></script>
<style>
  :root {{
    --navy: #1a2332;
    --blue: #2563eb;
    --blue-light: #3b82f6;
    --slate: #334155;
    --gray-100: #f1f5f9;
    --gray-200: #e2e8f0;
    --gray-400: #94a3b8;
    --gray-600: #475569;
    --gray-800: #1e293b;
    --red: #dc2626;
    --amber: #d97706;
    --green: #16a34a;
    --teal: #0d9488;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: var(--gray-800);
    background: var(--gray-100);
    line-height: 1.65;
  }}
  .report-container {{
    max-width: 1200px;
    margin: 0 auto;
    background: #fff;
  }}
  /* Header */
  .report-header {{
    background: linear-gradient(135deg, var(--navy) 0%, #0f172a 100%);
    color: #fff;
    padding: 60px 48px 48px;
  }}
  .report-header h1 {{
    font-size: 2.25rem;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }}
  .report-header .subtitle {{
    font-size: 1.1rem;
    opacity: 0.85;
    margin-bottom: 24px;
  }}
  .report-header .meta {{
    display: flex;
    gap: 24px;
    font-size: 0.85rem;
    opacity: 0.7;
  }}
  /* KPI strip */
  .kpi-strip {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1px;
    background: var(--gray-200);
  }}
  .kpi-card {{
    background: #fff;
    padding: 28px 24px;
    text-align: center;
  }}
  .kpi-card .value {{
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--navy);
  }}
  .kpi-card .label {{
    font-size: 0.8rem;
