import csv
import json
import math
from datetime import datetime

# ── Load Data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append({
            "date": row["Date"],
            "price": float(row["Crude_Oil_Price"])
        })

# ── Parse dates ────────────────────────────────────────────────────────────
for r in rows:
    parts = r["date"].split("-")
    r["year"] = int(parts[0])
    r["month"] = int(parts[1])
    r["decade"] = (r["year"] // 10) * 10

prices = [r["price"] for r in rows]
dates_str = [r["date"] for r in rows]
n = len(prices)

# ── KPI Calculations ──────────────────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
price_range = max_price - min_price
mean_price = sum(prices) / n
sorted_prices = sorted(prices)
median_price = (sorted_prices[n // 2 - 1] + sorted_prices[n // 2]) / 2 if n % 2 == 0 else sorted_prices[n // 2]
std_dev = math.sqrt(sum((p - mean_price) ** 2 for p in prices) / n)

# Percentiles
def percentile(data, pct):
    idx = (pct / 100) * (len(data) - 1)
    lower = int(math.floor(idx))
    upper = int(math.ceil(idx))
    if lower == upper:
        return data[lower]
    return data[lower] + (data[upper] - data[lower]) * (idx - lower)

p10 = percentile(sorted_prices, 10)
p25 = percentile(sorted_prices, 25)
p75 = percentile(sorted_prices, 75)
p90 = percentile(sorted_prices, 90)

# CAGR
first_price = prices[0]
last_price = prices[-1]
first_year = rows[0]["year"]
last_year = rows[-1]["year"]
years_span = last_year - first_year
cagr = (last_price / first_price) ** (1 / years_span) - 1

# Month-over-month changes
mom_abs_changes = []
mom_pct_changes = []
for i in range(1, n):
    abs_change = prices[i] - prices[i - 1]
    pct_change = (abs_change / prices[i - 1]) * 100 if prices[i - 1] != 0 else 0
    mom_abs_changes.append({
        "from_date": dates_str[i - 1],
        "to_date": dates_str[i],
        "abs_change": abs_change,
        "pct_change": pct_change
    })
    mom_pct_changes.append(pct_change)

max_mom_abs = max(mom_abs_changes, key=lambda x: abs(x["abs_change"]))
max_mom_pct = max(mom_abs_changes, key=lambda x: abs(x["pct_change"]))

# Year-over-year changes (same month, previous year)
yoy_changes = []
for i in range(12, n):
    yoy_change = (prices[i] - prices[i - 12]) / prices[i - 12] * 100 if prices[i - 12] != 0 else 0
    yoy_changes.append({
