// ── 4. Price Distribution Histogram ──
(function() {{
  const ctx = document.getElementById('chartDistribution').getContext('2d');
  const prices = {chart_prices_json};

  // Create histogram bins
  const min = 0;
  const max = 140;
  const binWidth = 10;
  const bins = [];
  const labels = [];
  for (let i = min; i < max; i += binWidth) {{
    bins.push(0);
    labels.push('$' + i + '-$' + (i + binWidth));
  }}
  prices.forEach(p => {{
    const idx = Math.min(Math.floor((p - min) / binWidth), bins.length - 1);
    if (idx >= 0) bins[idx]++;
  }});

  new Chart(ctx, {{
    type: 'bar',
    data: {{
      labels: labels,
      datasets: [{{
        label: 'Frequency',
        data: bins,
        backgroundColor: 'rgba(37,99,235,0.65)',
        borderColor: BLUE,
        borderWidth: 1
      }}]
    }},
    options: {{
      responsive: true,
